// Parse Claude's JSON reply + resolve to Krayin IDs
const ctx = $('Auth + parse').first().json;
const raw = $input.first().json?.content?.[0]?.text || '{}';

// Strip any accidental ```json fences
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();

let parsed;
try { parsed = JSON.parse(cleaned); }
catch (e) {
  throw new Error('Claude returned non-JSON: ' + cleaned.slice(0, 200));
}

const SEGMENT_TO_OPTION = { healthcare: 1, iso: 2, pdpl: 3, other: 4 };
const PRACTITIONER_TO_USER = { manoj: 2, nelson: 5, vinoth: 6 };

const score = Math.max(0, Math.min(100, parseInt(parsed.score) || 0));
const segmentKey = (parsed.segment || 'other').toLowerCase();
const practitionerKey = (parsed.suggested_practitioner || 'manoj').toLowerCase();

const segmentOptionId = SEGMENT_TO_OPTION[segmentKey] || 4;
const suggestedUserId = PRACTITIONER_TO_USER[practitionerKey] || 2;

// Stage move logic
const MQL_STAGE = 14;  // pipeline 4 MQL
let newStageId = null;
let category = 'low_fit';
if (score >= 70) { newStageId = MQL_STAGE; category = 'hot'; }
else if (score >= 40) { category = 'nurture'; }

return {
  lead_id: ctx.lead_id,
  person_id: ctx.person_id,
  source: ctx.source,
  payload: ctx.payload,
  scoring: {
    score,
    segment: segmentKey,
    segment_option_id: segmentOptionId,
    suggested_practitioner: practitionerKey,
    suggested_user_id: suggestedUserId,
    suggested_first_offer: parsed.suggested_first_offer || '',
    reasoning: parsed.reasoning || '',
    category,
    new_stage_id: newStageId,
  }
};

